-- Caso de excedente confirmado por el propietario; sólo contenido editorial.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('pago-excedente-400-devolucion-100',$texto$Recibir $400 para un cargo de $300 y devolver $100 sin reabrir deuda$texto$,'Cobranza',$texto$Registrar dinero recibido de más, aplicar sólo el saldo del cargo y devolver el excedente conservando el abono y la liquidación.$texto$,$texto$Inscripción vigente, tutor responsable financiero con acceso familiar y banco activo del plantel/moneda. Administrador persistido autorizado para conceptos, cuotas, adeudos, pagos, validación, devoluciones y cuentas. Concepto sin beca, descuento ni recargo. Usar datos controlados y fechas dentro de inscripción/ciclo. Si ya realizaste el ejemplo, consultar sus resultados sin repetir operaciones. Dejar fuera el adeudo anterior de $400.00 y los cargos de $600.00/$400.00 ya liquidados.$texto$,$texto$Cargo EXC-TEST $300.00. Recibido $400.00, aplicado $300.00 y disponible $100.00. Validar aumenta el banco B a B + $400.00. Devolver parcialmente $100.00 consume sólo el excedente: aplicado $300.00, devuelto $100.00, disponible $0.00, cargo liquidado y banco B + $300.00. El adeudo anterior de $400.00 queda intacto. El propietario confirmó todos estos resultados el 08/10/2026.$texto$,1,DATE '2026-10-08','CONFIRMADA');
INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['CONCEPTO_COBRO_ADMINISTRAR','CUOTA_ALUMNO_ADMINISTRAR','CARGO_ADMINISTRAR','PAGO_LEER','PAGO_REGISTRAR','PAGO_VALIDAR','PAGO_DEVOLVER','CUENTA_FINANCIERA_LEER']) WHERE g.slug='pago-excedente-400-devolucion-100';
INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('pago-excedente-400-devolucion-100',1,$texto$Preparar el concepto de prueba sin ajustes$texto$,$texto$Administración$texto$,$texto$Conceptos de cobro$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Conceptos de cobro. Busca EXC-TEST y pulsa Aplicar filtros. 2. Si ya existe, verifica institución y que sea un concepto de prueba; reutilízalo. Si no existe, pulsa Nuevo registro y selecciona institución, Código EXC-TEST, Nombre Prueba de pago con excedente y Categoría Otro. 3. Marca Concepto activo; deja Permite beca, Permite descuento y Permite recargo desmarcados. Pulsa Crear concepto. 4. Regresa al listado y confirma código/nombre, sin modificar conceptos reales ni duplicar el ejemplo ya ejecutado.$texto$,$texto$EXC-TEST identifica el cargo nuevo de $300.00.$texto$,$texto$Concepto disponible, sin ajustes.$texto$,$texto$El excedente no es otro concepto ni otra deuda; es parte del dinero recibido que aún no está asignada a cargos.$texto$,$texto$/admin/catalogos/conceptos-cobro$texto$),
('pago-excedente-400-devolucion-100',2,$texto$Crear una cuota única de $300$texto$,$texto$Administración$texto$,$texto$Cuotas por alumno$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Cuotas por alumno → Nuevo registro; si la cuota del ejercicio ya existe, consúltala sin crear otra. 2. Selecciona institución, plantel, Inscripción vigente del alumno y Concepto de cobro EXC-TEST. Captura Importe individual 300.00 y moneda institucional MXN si corresponde. 3. Configura Una sola vez, Fecha límite de pago 20/10/2026 y Estado Activa; activa Incluir en generación automática de cargos. En Configuración adicional verifica vigencia dentro de inscripción/ciclo; adapta fechas si octubre no pertenece a la inscripción. 4. Revisa Así quedará la cuota → Crear cuota; comprueba alumno, importe y fechas en el modal y confirma. Anota la cuota para identificarla al generar.$texto$,$texto$Cuota única $300.00, sin becas ni recargos.$texto$,$texto$Cuota preparada, todavía sin pago recibido.$texto$,$texto$No usar la deuda anterior de $400.00 ni las cuotas de los dos cargos ya liquidados.$texto$,$texto$/admin/cuotas-alumno/nuevo$texto$),
('pago-excedente-400-devolucion-100',3,$texto$Generar sólo el adeudo EXC-TEST$texto$,$texto$Administración$texto$,$texto$Adeudos de alumnos → Generar automáticos$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos → Generar automáticos. Selecciona institución y Generar hasta 08/10/2026 si esa fecha pertenece a la vigencia de la cuota; si adaptaste fechas, utiliza una válida. 2. Pulsa Visualizar cuotas por aplicar → Desmarcar todos y selecciona únicamente EXC-TEST por $300.00 del alumno de prueba. Revisa importe y descuentos cero. 3. Pulsa Confirmar y generar adeudos seleccionados; revisa el modal y confirma una sola vez. Si ya fue generado, consulta el original sin duplicar la cuota. 4. Pulsa Volver a adeudos de alumnos, busca matrícula → Con saldo pendiente → Aplicar filtros → Ver del nuevo cargo. Confirma total $300.00, pagado $0.00 y saldo $300.00; anota su número.$texto$,$texto$Un cargo EXC-TEST de $300.00.$texto$,$texto$Deuda independiente identificada.$texto$,$texto$Generar un cargo no recibe dinero. No seleccionar otras cuotas de prueba.$texto$,$texto$/admin/cargos/generar$texto$),
('pago-excedente-400-devolucion-100',4,$texto$Anotar el saldo bancario de referencia$texto$,$texto$Administración$texto$,$texto$Cuentas financieras$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras. Busca el banco de prueba y pulsa Aplicar filtros. 2. Anota Saldo actual como B y conserva código/nombre de cuenta; por ejemplo B = $2,000.00. No captures ese valor en un formulario. 3. Confirma cuenta activa, plantel y moneda compatible; se usará la misma cuenta al validar y al devolver. 4. No registres movimientos manuales ni cambies saldo inicial. Sin otras operaciones, se esperan B + $400.00 después de validar y B + $300.00 después de devolver.$texto$,$texto$Referencia B para comprobar ingreso y egreso.$texto$,$texto$Cuenta identificada y saldo anotado.$texto$,$texto$Identifica por separado movimientos ajenos durante la prueba para no atribuirlos al pago.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('pago-excedente-400-devolucion-100',5,$texto$Recibir $400 y distribuir sólo $300$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Nuevo registro$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos → Nuevo registro. Selecciona institución, plantel y tutor del alumno en Origen y responsable. 2. En Adeudos que se van a pagar pulsa Agregar cargo y selecciona únicamente EXC-TEST por $300.00; conserva el importe completo, sin activar Registrar pago parcial. Abre Alternativa: registrar dinero pendiente de asignar y activa Capturar un total recibido diferente de la distribución. 3. En Datos del pago captura Total recibido 400.00, Método Tarjeta, Cuenta declarada bancaria anotada, fecha/hora reales y referencia TEST-EXCEDENTE-400. En Observaciones escribe Pago de $400 para un cargo de $300; excedente de $100 por devolver. Adjunta comprobante de prueba si corresponde. 4. En Revisa y registra verifica total recibido $400.00, distribuido $300.00, dinero pendiente de asignar $100.00 y Quedará por pagar $0.00 del cargo. Pulsa Registrar como pendiente → revisa modal → Confirmar y registrar como pendiente; anota el folio.$texto$,$texto$Recibido $400.00 = distribución $300.00 + sin asignar $100.00.$texto$,$texto$Pago pendiente con excedente explícito.$texto$,$texto$No aumentar la asignación del cargo a $400.00: sólo debe cubrir su saldo de $300.00. El dinero sin asignar no liquida automáticamente otras deudas.$texto$,$texto$/admin/pagos/nuevo$texto$),
('pago-excedente-400-devolucion-100',6,$texto$Validar y comprobar disponible $100$texto$,$texto$Administración y tutor$texto$,$texto$Pagos recibidos, cuentas y portal familiar$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos; busca TEST-EXCEDENTE-400 → Aplicar filtros → Ver → Gestión → Control administrativo del pago. Conserva cuenta bancaria → Validar y publicar → revisa modal y confirma una sola vez. 2. En el mismo pago abre Distribución: Aplicado $300.00, Devuelto $0.00 y Disponible $100.00. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos, busca matrícula → Liquidado — saldo $0 → Aplicar filtros → Ver de EXC-TEST; confirma pagado $300.00 y saldo $0.00. 3. Entra a Administración → Finanzas → Cuentas financieras; busca banco → Aplicar filtros y verifica B + $400.00. No sumar sólo $300.00: se recibió dinero adicional. 4. En una ventana privada entra a /familias, inicia sesión con el tutor → selecciona el hijo → Tus pagos y recarga. EXC-TEST no debe aparecer pendiente; la deuda anterior de $400.00 sí permanece. Regresa a la ventana administrativa.$texto$,$texto$Banco B + $400.00; cargo liquidado; disponible $100.00.$texto$,$texto$Ingreso completo y excedente conservado, sin pagar otro cargo.$texto$,$texto$No crear entrada manual adicional ni otro pago para reflejar el excedente.$texto$,$texto$/admin/catalogos/pagos$texto$),
('pago-excedente-400-devolucion-100',7,$texto$Devolver parcialmente el excedente sin liberar el abono$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Devoluciones$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos; busca el folio TEST-EXCEDENTE-400 → Aplicar filtros → Ver → Devoluciones. Conserva Cuenta de origen precargada, sin activar Devolver desde otra cuenta. 2. Captura fecha/hora actuales no anteriores al pago, Tipo de devolución Parcial, Dinero a devolver 100.00 y Beneficiario con nombre del tutor. Referencia TEST-DEV-EXCEDENTE-100 y Motivo: Devolución de $100 recibidos de más; se conserva liquidado el cargo de $300. 3. En Abonos de los que se devolverá dinero selecciona el abono de $300.00 de EXC-TEST; el sistema utiliza primero Disponible $100.00. Revisa Así quedaría la devolución: dinero a devolver $100.00, abono seleccionado que permanecerá aplicado $300.00, deuda que se recuperará $0.00 y saldo del cargo después de devolver $0.00. 4. Sólo si coincide pulsa Ejecutar devolución y publicar egreso, revisa cuenta/importe/deuda en el modal y confirma. Cancelar cierra sin ejecutar y conserva captura. Espera devolución Ejecutada y su historial.$texto$,$texto$Se devuelve disponible $100.00; aplicado $300.00 no se libera.$texto$,$texto$Egreso $100.00 sin reabrir deuda.$texto$,$texto$No elegir Total con el abono seleccionado: incluiría también su importe. Si la vista muestra deuda recuperada distinta de cero, detenerse sin confirmar.$texto$,$texto$/admin/catalogos/pagos$texto$),
('pago-excedente-400-devolucion-100',8,$texto$Comprobar banco neto, cargo liquidado e historial$texto$,$texto$Administración y tutor$texto$,$texto$Pagos, cuentas, adeudos y portal familiar$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos; busca folio → Aplicar filtros → Ver → Distribución. Comprueba Aplicado $300.00, Devuelto $100.00 y Disponible $0.00. En Devoluciones identifica importe, motivo y cuenta; el pago original permanece Validado y su importe recibido sigue siendo $400.00. 2. Entra a Administración → Finanzas → Cuentas financieras; busca banco → Aplicar filtros y verifica B + $300.00, resultado de ingreso $400.00 menos egreso $100.00. No modificar el saldo para cuadrarlo. 3. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca matrícula → Liquidado — saldo $0 → Aplicar filtros → Ver de EXC-TEST. Confirma abono $300.00 y saldo $0.00. Cambia a Con saldo pendiente para verificar deuda anterior $400.00 intacta. En la ventana familiar entra a /familias → selecciona hijo → Tus pagos y recarga: los $300.00 no reaparecen. 4. Para consultar evidencia vuelve a Administración → Finanzas → Pagos recibidos; busca folio → Aplicar filtros → Exportar Excel. En Ver → Comprobantes abre el PDF en otra pestaña y conserva historial de devolución por separado. No repetir el egreso al leer la guía.$texto$,$texto$Recibido $400.00, aplicado $300.00, devuelto $100.00, disponible $0.00; banco B + $300.00.$texto$,$texto$El propietario confirmó que toda la prueba cumplió: devolución del excedente sin reabrir deuda y saldo neto correcto.$texto$,$texto$El total original del pago no se reescribe a $300.00: pago y devolución son hechos distintos que deben conservarse.$texto$,$texto$/admin/catalogos/pagos$texto$)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;
